<?php require_once "../config/auth.php";require_login();$u=user();$q=db()->prepare("SELECT o.*,s.name service_name FROM orders o JOIN services s ON s.id=o.service_id WHERE o.user_id=? ORDER BY o.id DESC");$q->execute([$u["id"]]);$rows=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><main><div class="box wide"><h1>My Orders</h1><div class="table"><table><tr><th>ID</th><th>Service</th><th>Qty</th><th>Charge</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td>#<?=$r["id"]?></td><td><?=e($r["service_name"])?></td><td><?=$r["quantity"]?></td><td>৳<?=number_format($r["charge"],2)?></td><td><?=$r["status"]?></td></tr><?php endforeach;?></table></div></div></main></body></html>